/**
 * Version Refresh Boot File
 *
 * This boot file initializes the version refresh service that detects when a new
 * version is deployed and forces a hard refresh to prevent users from loading
 * stale JavaScript bundles.
 *
 * Boot files are automatically executed by Quasar during app startup, before the
 * root Vue component is mounted.
 */

import { boot } from 'quasar/wrappers';
import { initializeVersionRefresh } from 'src/utils/versionRefresh';
import { safeBoot } from 'src/utils/bootSafety';

export default boot(safeBoot('versionRefresh', () => {
  // Initialize version refresh service
  // This will:
  // 1. Check current version vs deployed version on app startup
  // 2. Set up periodic checks every 30 seconds
  // 3. Listen for visibility changes (user returns from background)
  // 4. Force hard refresh if new version is detected
  initializeVersionRefresh();
}));
